# The show_song API only allows fetching one song at a time.
# Let's fetch details for all unique song_ids in the playlists (excluding "Archived Songs").
# We'll build a mapping from (title.lower(), artist.lower()) to song_id.

song_id_to_info = {}
for song_id in all_song_ids:
    song_info = apis.spotify.show_song(song_id=song_id)
    song_id_to_info[song_id] = song_info

# Now, build a mapping from (title.lower(), artist.lower()) to song_id(s).
title_artist_to_song_ids = {}
for song_id, info in song_id_to_info.items():
    title = info["title"].strip().lower()
    for artist in info["artists"]:
        artist_name = artist["name"].strip().lower()
        key = (title, artist_name)
        if key not in title_artist_to_song_ids:
            title_artist_to_song_ids[key] = []
        title_artist_to_song_ids[key].append(song_id)

print(title_artist_to_song_ids)  # For inspection before proceeding.

