# Now, let's match the old_songs list (which should be a list of dicts with "title" and "artist") to the songs in the playlists.
# We'll build a set of (title.lower(), artist.lower()) for old_songs for easy matching.
# Then, for each playlist, we'll find which song_ids correspond to old songs.

old_song_keys = set((s["title"].lower(), s["artist"].lower()) for s in old_songs)

# For each playlist, collect the song_ids to remove (those matching old_songs)
playlist_songs_to_remove = {}
for playlist in all_playlists:
    to_remove = []
    for song_id in playlist["song_ids"]:
        details = song_id_to_details.get(str(song_id))
        if details and (details["title"].lower(), details["artist"].lower()) in old_song_keys:
            to_remove.append(song_id)
    if to_remove:
        playlist_songs_to_remove[playlist["playlist_id"]] = to_remove

print(playlist_songs_to_remove)

# It looks like some old_songs have multiple artists (comma-separated), but the playlist song details only list a single artist.
# To match, let's check if the playlist song's artist is present (case-insensitive, substring match) in the old_songs artist string.
# We'll also strip whitespace for robustness.

def is_artist_match(song_artist, old_artist):
    # True if song_artist is a substring (case-insensitive, trimmed) of old_artist
    return song_artist.strip().lower() in [a.strip().lower() for a in old_artist.split(",")]

playlist_songs_to_remove = {}
for playlist in all_playlists:
    to_remove = []
    for song_id in playlist["song_ids"]:
        details = song_id_to_details.get(str(song_id)) or song_id_to_details.get(song_id)
        if not details:
            continue
        for old_song in old_songs:
            if (
                details["title"].strip().lower() == old_song["title"].strip().lower()
                and is_artist_match(details["artist"], old_song["artist"])
            ):
                to_remove.append(song_id)
                break
    if to_remove:
        playlist_songs_to_remove[playlist["playlist_id"]] = to_remove

print(playlist_songs_to_remove)

# Let's build a mapping from (title, artist) to song_id for all songs in the playlists.
# Then, for each old song (title, artist), we'll find its song_id if present in the playlists.
# We'll also keep track of which playlist(s) each old song appears in, so we can remove them and later add them to the "Archived Songs" playlist.

# Build mapping: (title.lower(), artist.lower()) -> song_id
song_lookup = {}
for song in songs_metadata:
    for artist in song["artists"]:
        key = (song["title"].strip().lower(), artist["name"].strip().lower())
        song_lookup[key] = song["song_id"]

# Build mapping: song_id -> [playlist_id, ...]
song_to_playlists = {}
for playlist in all_playlists:
    for sid in playlist["song_ids"]:
        song_to_playlists.setdefault(sid, []).append(playlist["playlist_id"])

# Find old songs that are present in playlists
old_song_ids_in_playlists = {}
for old_song in old_songs:
    title = old_song["title"].strip().lower()
    artist = old_song["artist"].strip().lower()
    key = (title, artist)
    if key in song_lookup:
        sid = song_lookup[key]
        if sid in song_to_playlists:
            old_song_ids_in_playlists.setdefault(sid, set()).update(song_to_playlists[sid])

print(old_song_ids_in_playlists)  # {song_id: set(playlist_ids), ...}

