steps.code:
# Now, let's determine which old songs (by Spotify song ID) are present in each playlist.
# We'll build a mapping: playlist_id -> list of old song IDs to remove from that playlist.

old_song_ids = set(song["spotify_song_id"] for song in json_friendly_mapping)
songs_to_remove_per_playlist = {}

for playlist_id, song_ids in playlist_songs.items():
    to_remove = [song_id for song_id in song_ids if song_id in old_song_ids]
    if to_remove:
        songs_to_remove_per_playlist[playlist_id] = to_remove

print(songs_to_remove_per_playlist)

# Now we need to remove the identified old songs from each playlist.
# We'll use the `remove_song_from_playlist` API for each (playlist_id, song_id) pair.

for playlist_id, song_ids in songs_to_remove_per_playlist.items():
    for song_id in song_ids:
        apis.spotify.remove_song_from_playlist(
            playlist_id=playlist_id,
            song_id=song_id,
            access_token=spotify_access_token
        )

