# Now, let's remove all old songs from their respective playlists.
# We'll iterate through each playlist and remove the old songs (by song_id) that are present in that playlist.

remove_results = []
for playlist_id, song_ids in playlist_old_songs.items():
    for song_id in song_ids:
        result = apis.spotify.remove_song_from_playlist(
            playlist_id=playlist_id,
            song_id=song_id,
            access_token=spotify_access_token
        )
        remove_results.append({
            "playlist_id": playlist_id,
            "song_id": song_id,
            "result": result
        })
print(remove_results)

