# Now let's reconstruct the set of old song Spotify IDs from old_song_to_spotify_id.
# Then, for each playlist, find which old songs are present and prepare a removal plan.

# Reconstruct old_song_spotify_ids
old_song_spotify_ids = set(entry["song_id"] for entry in old_song_to_spotify_id if entry.get("song_id") is not None)

# For each playlist, find which old songs are present
playlist_old_songs = {}
removal_plan = []
for playlist_id, song_ids in playlist_id_to_songs.items():
    old_songs_in_playlist = list(set(song_ids) & old_song_spotify_ids)
    if old_songs_in_playlist:
        playlist_old_songs[playlist_id] = old_songs_in_playlist
        removal_plan.append({
            "playlist_id": playlist_id,
            "songs_to_remove": old_songs_in_playlist
        })

print(removal_plan)

# The old_songs list is correctly populated with title and artist pairs.
# The next step is to search for each song on Spotify and map it to its song_id.
# Let's search for each song using spotify.search_songs and collect the best match for each (if any).
# We'll use the spotify_access_token and search by title and artist.

old_song_to_spotify_id = []
for song in old_songs:
    query = f"{song['title']} {song['artist']}"
    results = apis.spotify.search_songs(
        access_token=spotify_access_token,
        query=query,
        page_limit=5
    )
    # Try to find the best match by comparing title and artist (case-insensitive, partial match)
    best_match = None
    for result in results:
        title_match = song['title'].lower() in result['title'].lower()
        artist_match = any(
            song_artist.strip().lower() in artist['name'].lower()
            for song_artist in song['artist'].split(',')
            for artist in result.get('artists', [])
        )
        if title_match and artist_match:
            best_match = result
            break
    if best_match:
        old_song_to_spotify_id.append({
            "title": song['title'],
            "artist": song['artist'],
            "song_id": best_match['song_id']
        })
    else:
        old_song_to_spotify_id.append({
            "title": song['title'],
            "artist": song['artist'],
            "song_id": None
        })

print(old_song_to_spotify_id)

