# Now, let's identify which songs in each playlist are present in the songs_to_archive list.
# We'll create a mapping of playlist_id to the list of song IDs to be archived (i.e., to be removed from that playlist).

songs_to_archive_set = set(songs_to_archive)
songs_to_remove_from_playlists = {}

for playlist_id, song_ids in playlist_songs.items():
    to_remove = [song_id for song_id in song_ids if song_id in songs_to_archive_set]
    if to_remove:
        songs_to_remove_from_playlists[playlist_id] = to_remove

print(songs_to_remove_from_playlists)

