# Now, let's fetch details for all song_ids in all_song_ids to map their titles and artists.
# We'll store the mapping of song_id to (title, artist_names) for matching with the old songs list.
song_id_to_details = {}
for song_id in all_song_ids:
    resp = apis.spotify.show_song(song_id=song_id)
    if isinstance(resp, dict) and "song_id" in resp:
        artist_names = [artist["name"] for artist in resp.get("artists", [])]
        song_id_to_details[song_id] = {
            "title": resp.get("title", ""),
            "artists": artist_names
        }
print(song_id_to_details)

