steps.code:
# Now, let's match songs from all_song_details with the old songs in song_artist_list.
# We'll collect the song_ids of songs where both the title and all artists match (case-insensitive, ignoring order).
# We'll also store a mapping from song_id to the full song detail for later use.

def normalize(s):
    return s.strip().lower()

# Build a set of tuples (normalized_title, frozenset(normalized_artists)) for old songs
old_songs_set = set(
    (normalize(song["title"]), frozenset(normalize(a) for a in song["artists"]))
    for song in song_artist_list
)

archived_song_ids = []
archived_song_details = {}

for song in all_song_details:
    song_title = normalize(song["title"])
    song_artists = frozenset(normalize(a["name"]) for a in song["artists"])
    if (song_title, song_artists) in old_songs_set:
        archived_song_ids.append(song["song_id"])
        archived_song_details[song["song_id"]] = song

print(archived_song_ids)  # song_ids to archive
print([archived_song_details[sid]["title"] for sid in archived_song_ids])  # titles for confirmation

# Each playlist contains a "song_ids" field, so we can directly check which archived_song_ids are present in each playlist.
# Let's build a mapping: playlist_id -> list of archived_song_ids to remove from that playlist.

playlist_removals = {}
for playlist in playlists:
    to_remove = [sid for sid in playlist["song_ids"] if sid in archived_song_ids]
    if to_remove:
        playlist_removals[playlist["playlist_id"]] = to_remove

print(playlist_removals)  # playlist_id -> song_ids to remove

