# I need the Spotify access token to create the playlist. Let's check if I already have it, otherwise, I need to log in to Spotify.
# Let's check if a variable like `spotify_access_token` or similar is already defined.

try:
    spotify_access_token
except NameError:
    # I don't have the access token, so I need to get the Spotify password from supervisor and log in.
    print(apis.supervisor.show_account_passwords())
else:
    # If I already have the access token, proceed to create the playlist.
    print("HAVE_TOKEN", spotify_access_token)

