# The helper function works. Now, let's automate the search for all songs in todo_songs.
# We'll search each song by title and first artist, and extract the release month from the top matching result (if found).
release_months = []
for song in todo_songs:
    query = f"{song['title']} {song['artists'][0]}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the first result that matches both title and all artists (at least the first artist)
    match = None
    for result in results:
        if result["title"].lower() == song["title"].lower():
            result_artist_names = set(a["name"].lower() for a in result["artists"])
            song_artist_names = set(a.lower() for a in song["artists"])
            if song_artist_names.issubset(result_artist_names):
                match = result
                break
    if match:
        release_months.append(get_release_month(match["release_date"]))
    else:
        release_months.append(None)
print(release_months)

