steps.code:
# Now, for each song in todo_songs, let's search Spotify for the song using the title and artist as the query.
# We'll collect the release_date for each song. Let's do this for the first 5 songs as a batch to avoid hitting rate limits.

spotify_release_info = []

for song in todo_songs[:5]:
    query = f'{song["title"]} {song["artist"]}'
    result = apis.spotify.search_songs(query=query, page_limit=1)
    # If a result is found, extract the release_date
    if result and isinstance(result, list) and len(result) > 0:
        release_date = result[0].get("release_date")
        spotify_release_info.append({
            "title": song["title"],
            "artist": song["artist"],
            "release_date": release_date
        })
    else:
        spotify_release_info.append({
            "title": song["title"],
            "artist": song["artist"],
            "release_date": None
        })

print(spotify_release_info)

