steps.code:
# The first result matches the song title and artist exactly, and contains the release_date.
# Let's write a function to get the release month (MM/YYYY) for each song in todo_songs by searching Spotify.
# We'll collect the mapping: (song_title, artist_string) -> release_month.

from datetime import datetime

def get_release_month(song_title, artist_string):
    query = f"{song_title} {artist_string}"
    results = apis.spotify.search_songs(query=query, page_limit=3)
    # Find the result with exact title and at least one matching artist
    for song in results:
        if song["title"].lower() == song_title.lower():
            artist_names = [a["name"].lower() for a in song["artists"]]
            # Check if any artist in artist_string matches
            for artist in [a.strip().lower() for a in artist_string.split(",")]:
                if artist in artist_names:
                    # Parse release_date to MM/YYYY
                    dt = datetime.fromisoformat(song["release_date"])
                    return f"{dt.month:02d}/{dt.year}"
    return None

release_months = {}
for song_title, artist_string in todo_songs:
    release_month = get_release_month(song_title, artist_string)
    release_months[(song_title, artist_string)] = release_month

print(release_months)

# The error is because dictionaries with tuple keys can't be printed as JSON.
# Let's print the results as a list of dicts for clarity.

release_months_list = [
    {"song_title": song_title, "artist_string": artist_string, "release_month": release_month}
    for (song_title, artist_string), release_month in release_months.items()
]
print(release_months_list)

