{
 "app_name": "spotify",
 "api_name": "remove_song_from_queue",
 "path": "/music_player/song_queue/{position}",
 "method": "DELETE",
 "description": "Remove a song at the given position from the music player song queue.",
 "parameters": [
  {
   "name": "position",
   "type": "integer",
   "required": true,
   "description": "The 0-indexed position of the song in the queue.",
   "default": null,
   "constraints": []
  },
  {
   "name": "access_token",
   "type": "string",
   "required": true,
   "description": "Access token obtained from spotify app login.",
   "default": null,
   "constraints": []
  }
 ],
 "response_schemas": {
  "success": {
   "message": "string"
  },
  "failure": {
   "message": "string"
  }
 }
}

steps.code:
# Let's remove the songs at these positions from the queue, starting from the highest position to avoid shifting issues.
for pos in positions_to_remove:
    apis.spotify.remove_song_from_queue(position=pos, access_token=access_token)

